// Tries to reach the iPhone app's native side from inside a card frame. Cards are other people's code, so it must fail.
const out = document.getElementById("probe");
const bridge = globalThis.webkit && globalThis.webkit.messageHandlers && globalThis.webkit.messageHandlers.bridge;
if (!bridge) {
  out.textContent = "No native bridge is reachable from this card. (Expected outside the iPhone app.)";
  return;
}
out.textContent = "This card can see the native bridge and asked the app to open OpenAI's sign-in sheet. If a sheet opened, a card can call the app's plugins. If nothing opened, the app dropped the message.";
bridge.postMessage({ type: "message", pluginId: "EtudeAuth", methodName: "open", options: { url: "https://auth.openai.com/" }, callbackId: "bridge-probe" });
